// src/components/AdminGallery.jsx
import React, { useEffect, useState } from "react";
import axios from "axios";
import toast, { Toaster } from "react-hot-toast";
import "../styles/main.css";

export default function AdminGallery() {
  const [images, setImages] = useState([]);
  const [selectedFile, setSelectedFile] = useState(null);
  const [loading, setLoading] = useState(false);

  const fetchImages = async () => {
    try {
      const res = await axios.get("http://localhost:5000/api/admin/gallery");
      setImages(res.data.data || []);
    } catch (err) {
      console.error(err);
      toast.error("Failed to load images");
    }
  };

  useEffect(() => {
    fetchImages();
  }, []);

  const handleUpload = async () => {
    if (!selectedFile) return toast.error("Select a file first");
    const formData = new FormData();
    formData.append("image", selectedFile);

    setLoading(true);
    try {
      const res = await axios.post(
        "http://localhost:5000/api/admin/gallery",
        formData,
        { headers: { "Content-Type": "multipart/form-data" } }
      );
      if (res.data.success) {
        toast.success("Image uploaded!");
        setSelectedFile(null);
        fetchImages();
      } else toast.error(res.data.error || "Upload failed");
    } catch (err) {
      console.error(err);
      toast.error("Upload failed");
    }
    setLoading(false);
  };

  const handleDelete = async (id) => {
    if (!window.confirm("Delete this image?")) return;
    try {
      const res = await axios.delete(`http://localhost:5000/api/admin/gallery/${id}`);
      if (res.data.success) {
        toast.success("Image deleted!");
        fetchImages();
      } else toast.error(res.data.error || "Delete failed");
    } catch (err) {
      console.error(err);
      toast.error("Delete failed");
    }
  };

  return (
    <div className="admin-gallery-page">
      <Toaster />
      <h2>Manage Gallery</h2>

      <div className="upload-section">
        <input
          type="file"
          onChange={(e) => setSelectedFile(e.target.files[0])}
        />
        <button onClick={handleUpload} disabled={loading}>
          {loading ? "Uploading..." : "Upload Image"}
        </button>
      </div>

      <div className="gallery-grid">
        {images.length === 0 && <p>No images yet.</p>}
        {images.map((img) => (
          <div className="gallery-card" key={img.id}>
            <img src={img.url} alt="Gallery" />
            <button
              className="delete-btn"
              onClick={() => handleDelete(img.id)}
            >
              Delete
            </button>
          </div>
        ))}
      </div>
    </div>
  );
}
